python3 << 'PYEOF'
import xml.etree.ElementTree as ET

NS = {
    'bpmn':   'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

tree = ET.parse('MultiInstanceIteratorBpmn/MultiInstanceIteratorBpmn.bpmn')
root = tree.getroot()

errors = []

# --- Checklist 1: root is definitions with BPMN + uipath namespaces ---
assert root.tag == '{http://www.omg.org/spec/BPMN/20100524/MODEL}definitions', "Wrong root tag"
print("CHECK 1 PASS: root is bpmn:definitions with correct namespace")

# --- Checklist 2: exactly one BPMNDiagram, shape per node, edge per flow ---
diagrams = root.findall('.//bpmndi:BPMNDiagram', NS)
assert len(diagrams) == 1, f"Expected 1 BPMNDiagram, got {len(diagrams)}"
print(f"CHECK 2a PASS: 1 BPMNDiagram present")

shapes = root.findall('.//bpmndi:BPMNShape', NS)
edges  = root.findall('.//bpmndi:BPMNEdge',  NS)
shape_ids = {s.get('bpmnElement') for s in shapes}
edge_ids  = {e.get('bpmnElement') for e in edges}
print(f"CHECK 2b: {len(shapes)} BPMNShapes, {len(edges)} BPMNEdges")

# Collect all flow nodes and sequence flows
all_ids = {}
for el in root.iter():
    eid = el.get('id')
    if eid:
        all_ids[eid] = el.tag

flow_node_tags = {
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}startEvent',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}endEvent',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}subProcess',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}scriptTask',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}task',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}exclusiveGateway',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}parallelGateway',
}
seq_flow_tag = '{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow'

flow_nodes = [eid for eid, tag in all_ids.items() if tag in flow_node_tags]
seq_flows  = [eid for eid, tag in all_ids.items() if tag == seq_flow_tag]

print(f"  Flow nodes found: {sorted(flow_nodes)}")
print(f"  Sequence flows found: {sorted(seq_flows)}")

# Each flow node should have a shape
missing_shapes = [n for n in flow_nodes if n not in shape_ids]
if missing_shapes:
    errors.append(f"FAIL: nodes missing BPMNShape: {missing_shapes}")
else:
    print("CHECK 2c PASS: every flow node has a BPMNShape")

# Each sequence flow should have an edge
missing_edges = [f for f in seq_flows if f not in edge_ids]
if missing_edges:
    errors.append(f"FAIL: flows missing BPMNEdge: {missing_edges}")
else:
    print("CHECK 2d PASS: every sequence flow has a BPMNEdge")

# --- Checklist 3: all *Ref attributes resolve ---
ref_attrs = ['sourceRef','targetRef','attachedToRef','default','messageRef','errorRef','escalationRef']
broken_refs = []
for el in root.iter():
    for attr in ref_attrs:
        val = el.get(attr)
        if val and val not in all_ids:
            broken_refs.append((el.get('id','?'), attr, val))
if broken_refs:
    errors.append(f"FAIL: broken *Ref: {broken_refs}")
else:
    print("CHECK 3 PASS: all *Ref attributes resolve to declared ids")

# --- Checklist 4: XOR gateways have conditions on non-default flows ---
for gw in root.findall('.//{http://www.omg.org/spec/BPMN/20100524/MODEL}exclusiveGateway'):
    default_flow = gw.get('default')
    outgoing_ids = [o.text.strip() for o in gw.findall('{http://www.omg.org/spec/BPMN/20100524/MODEL}outgoing')]
    for fid in outgoing_ids:
        if fid == default_flow:
            continue
        # find the flow
        flow = root.find(f'.//*[@id="{fid}"]')
        cond = flow.find('{http://www.omg.org/spec/BPMN/20100524/MODEL}conditionExpression') if flow is not None else None
        if cond is None:
            errors.append(f"FAIL: XOR gateway {gw.get('id')} non-default flow {fid} missing conditionExpression")
print("CHECK 4: XOR gateway condition check done (no XOR gateways = trivially pass)")

# --- Checklist 5: no activity/event has more than one incoming flow ---
for el in root.iter():
    if el.tag in flow_node_tags - {'{http://www.omg.org/spec/BPMN/20100524/MODEL}subProcess'}:
        incoming = el.findall('{http://www.omg.org/spec/BPMN/20100524/MODEL}incoming')
        if len(incoming) > 1:
            errors.append(f"FAIL: {el.get('id')} has {len(incoming)} incoming flows (max 1 for activities/events)")
print("CHECK 5 PASS: no activity/event has multiple incoming flows")

# --- Checklist 6: event subprocesses have one start event with event definition ---
for sp in root.findall('.//{http://www.omg.org/spec/BPMN/20100524/MODEL}subProcess'):
    if sp.get('triggeredByEvent') == 'true':
        starts = sp.findall('{http://www.omg.org/spec/BPMN/20100524/MODEL}startEvent')
        if len(starts) != 1:
            errors.append(f"FAIL: event subprocess {sp.get('id')} has {len(starts)} start events (need exactly 1)")
        # No event subprocesses in this file so this is trivially checked
print("CHECK 6: event subprocess check done (none present = trivially pass)")

# --- Checklist 7: vars.<id> references resolve to declared variables ---
declared_var_ids = set()
for v in root.findall('.//{http://uipath.org/schema/bpmn}input'):
    if v.get('id'): declared_var_ids.add(v.get('id'))
for v in root.findall('.//{http://uipath.org/schema/bpmn}output'):
    if v.get('id'): declared_var_ids.add(v.get('id'))
for v in root.findall('.//{http://uipath.org/schema/bpmn}inputOutput'):
    if v.get('id'): declared_var_ids.add(v.get('id'))
print(f"  Declared variable ids: {sorted(declared_var_ids)}")

# Check output var= attributes
for out_el in root.findall('.//{http://uipath.org/schema/bpmn}output[@var]'):
    vid = out_el.get('var')
    if vid not in declared_var_ids:
        errors.append(f"FAIL: uipath:output var='{vid}' not in declared variables")
print("CHECK 7 PASS: all uipath:output var= references resolve")

# --- Checklist 8: uipath:activity/event type is a child element, not attribute ---
for act in root.findall('.//{http://uipath.org/schema/bpmn}activity'):
    if act.get('type'):
        errors.append(f"FAIL: uipath:activity has type= attribute (must be child element)")
for evt in root.findall('.//{http://uipath.org/schema/bpmn}event'):
    if evt.get('type'):
        errors.append(f"FAIL: uipath:event has type= attribute (must be child element)")
print("CHECK 8 PASS: no type= attributes on uipath:activity/event wrappers")

# --- Verify multi-instance loopCharacteristics structure ---
mi_chars = root.findall('.//{http://www.omg.org/spec/BPMN/20100524/MODEL}multiInstanceLoopCharacteristics')
print(f"\nMulti-instance characteristics found: {len(mi_chars)}")
for mic in mi_chars:
    lc = mic.find('.//{http://uipath.org/schema/bpmn}loopCharacteristics')
    if lc is None:
        errors.append("FAIL: multiInstanceLoopCharacteristics missing uipath:loopCharacteristics extension")
    else:
        print(f"  uipath:loopCharacteristics: inputCollection='{lc.get('inputCollection')}' inputElement='{lc.get('inputElement')}'")
        assert lc.get('inputCollection') == '=vars.Var_Items', "inputCollection wrong"
        assert lc.get('inputElement') == 'iterator[0]', "inputElement must be 'iterator[0]' for subprocess depth"
        print("  PASS: inputCollection and inputElement are correct for subprocess depth")

# --- Verify script task args reference iterator[0] forms ---
import re
for el in root.iter():
    if el.tag == '{http://uipath.org/schema/bpmn}input' and el.get('name') == 'args':
        body = el.text or ''
        print(f"\nScript args body: {body.strip()}")
        if 'iterator[0].item' in body:
            print("  PASS: uses iterator[0].item (subprocess-depth form)")
        if 'iterator[0].loopCounter' in body:
            print("  PASS: uses iterator[0].loopCounter (subprocess-depth form)")
        if 'iterator.item' in body and 'iterator[0].item' not in body:
            errors.append("FAIL: uses bare iterator.item (task-level form) inside subprocess body")
        if 'iterator.loopCounter' in body and 'iterator[0].loopCounter' not in body:
            errors.append("FAIL: uses bare iterator.loopCounter inside subprocess body")

# --- Summary ---
print("\n=== VALIDATION SUMMARY ===")
if errors:
    for e in errors:
        print(e)
    print(f"\nFAILED: {len(errors)} error(s)")
else:
    print("ALL CHECKS PASSED - BPMN is structurally valid")
PYEOF

